from pathlib import Path
import collections,difflib,hashlib,json,shutil,tarfile
OUT=Path('/tmp/vw-story31-mutations');ROOT=Path('/home/sixtocantolla/sessions/day-to-day/vaultwarden-bind-ssh-key-fixed-operation');DEST=ROOT/'docs/implementation/3-1-evidence/mutations'
initial=json.loads((OUT/'initial-results.json').read_text());extra=json.loads((OUT/'extra-results.json').read_text());fixed=json.loads((OUT/'post-fix-results.json').read_text());plan=json.loads((OUT/'plan.json').read_text())
initial_cases=[r for r in initial+extra if r['classification']!='baseline-pass'];assert len(initial_cases)==52
reruns={r['name'].removeprefix('fixed-'):r for r in fixed if r['name'].startswith('fixed-')};cases=[]
for result in initial_cases:
 name=result['name'];last=reruns.get(name,result);assert last['classification']=='killed',(name,last)
 cases.append(dict(name=name,initial=result['classification'],final=last['classification'],initial_exit=result['exit'],final_exit=last['exit'],initial_seconds=result['seconds'],rerun_seconds=last['seconds'] if name in reruns else None,initial_evidence=name,final_evidence=last['name']))
original=json.loads((OUT/'original-source-hashes.json').read_text());post=json.loads((OUT/'post-fix-source-hashes.json').read_text());final=json.loads((OUT/'post-fix-final-source-hashes.json').read_text());assert post==final
assert post=={n:hashlib.sha256((ROOT/n).read_bytes()).hexdigest() for n in post}
assert original==json.loads((OUT/'initial-final-source-hashes.json').read_text())==json.loads((OUT/'extra-final-source-hashes.json').read_text())
changed=[n for n in original if original[n]!=post[n]];assert changed==['src/access/policy.rs','src/access/ports.rs','src/adapters/vaultwarden.rs','tests/ui/direct-request.mjs']
DEST.mkdir(exist_ok=False);(DEST/'diffs').mkdir()
for case in cases:
 shutil.copy2(OUT/case['name']/'change.diff',DEST/'diffs'/(case['name']+'.diff'))
for filename in ['prepare.py','initial-runner.py','runner.py','rerun.py','extra.py','archive.py','add_independent_tests.py','plan.json','initial-plan.json','test-improvements.diff','expected-ssh-v3-projection.json']:
 shutil.copy2(OUT/filename,DEST/filename)
baselines=[r for r in initial+fixed if r['classification']=='baseline-pass'];summary=dict(initial_counts=dict(collections.Counter(r['classification'] for r in initial_cases)),final_counts=dict(collections.Counter(r['final'] for r in cases)),survivor_reruns=len(reruns),baselines=baselines,changed_test_files=changed,production_changes_for_survivors=False,original_source_restored=True,final_source_restored=True,cases=cases)
(DEST/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
# Detailed repetitive hashes and run logs stay compressed; diffs/results remain reviewable.
with tarfile.open(DEST/'case-evidence.tar.gz','w:gz',compresslevel=9) as archive:
 for p in sorted(OUT.iterdir()):
  if p.is_dir() and (p/'result.json').exists():
   for item in sorted(p.iterdir()):
    if item.is_file():archive.add(item,arcname=p.name+'/'+item.name,recursive=False)
  elif p.is_file() and (p.name.endswith(('-hashes.json','-results.json','.log')) or p.name=='test-improvements.diff'):
   archive.add(p,arcname=p.name,recursive=False)
(DEST/'archive.sha256').write_text(hashlib.sha256((DEST/'case-evidence.tar.gz').read_bytes()).hexdigest()+'  case-evidence.tar.gz\n')
lines=['# Story 3.1 semantic mutation evidence','','All 52 independent mutants were killed: 43 by the initial tests and 9 after test-only improvements. There are no unresolved survivors, equivalent claims, unviable mutants, timeouts, or infrastructure failures. No production changes were needed.','','## Method and baselines','','The campaign used `/tmp/vw-story31-mutations/source`, a separate copy of the reviewed worktree. Each candidate changed one behavior, ran to completion, and restored its source before the next candidate. Each case records its diff, full command, exit code, assertions, elapsed time, candidate hashes and restored hashes. The original and final restoration manifests match their corresponding baselines. Root source changes during the campaign were limited to four test files.','','Initial unmodified baselines: SSH-focused tests 14/14, unsupported-backend denial 1/1, and trusted Firefox browser suite. After test improvements: SSH-focused tests 16/16 and the trusted Firefox browser suite. The parent workflow owns the complete final regression suite.','','## Measured gaps and test improvements','','- Exact duplicate JSON spelling was not independently tested; added valid-payload duplicates for identity, numeric type, deletion, SSH object and all three required key fields.','- The policy verifier default denial lacked a direct SSH test; added an unsupported verifier whose login fallback panics.','- Fingerprint negatives combined invalid prefix/encoding/size; added otherwise-valid wrong-prefix data, a single invalid base64 character, and 31/33-byte boundary vectors.','- Comparison-only digest tests could not detect omission of constant SSH use/profile members; added an independently calculated golden version-3 projection.','- Directory/pin review expectations reused the projection helper; replaced them with explicit expected values.','- Browser history searched for `ssh`, which also appeared in the operation ID; the history-only mutant proved this masking, and the assertion now requires `Backup SSH (ssh)`.','- Activation unknown-member coverage now explicitly includes remote, host, command, key path, options and working-directory selectors.','','The constant-field omissions are treated as revision-format regressions, not equivalents: omitting either changes the version-3 digest and would invalidate previously stored revisions. The independent golden fixture protects that serialization contract.','','## Completed cases','','| Mutant | Initial classification | Final classification | Initial / rerun seconds |','|---|---|---|---|']
for c in cases:
 duration=str(c['initial_seconds'])+(' / '+str(c['rerun_seconds']) if c['rerun_seconds'] is not None else '')
 lines.append(f"| `{c['name']}` | {c['initial']} | {c['final']} | {duration} |")
lines += ['','## Reproducibility and artifacts','','[Summary and exact results](summary.json), [single-change plan](plan.json), [test-only fixes](test-improvements.diff), and per-mutant patches in `diffs/` are readable directly. [Compressed per-case evidence](case-evidence.tar.gz) retains all logs, commands, individual results and full source/restoration manifests; its checksum is in `archive.sha256`. The archive includes both initial-survivor and successful rerun evidence.','','`prepare.py`, `initial-runner.py`, `runner.py`, `extra.py`, `rerun.py`, and `add_independent_tests.py` preserve the executed workflow. The scripts use the local secure-HOME test wrapper, existing Cargo target cache and installed browser dependencies; they never replace HOME or access a real backend account. Cargo dependency resolution ran offline and locked; fixtures used synthetic credentials and local servers.','','Initial mutants and reruns used `cargo test --offline --locked --lib ssh_`, except the unsupported backend mutation (the dedicated provider-session integration test) and actual rendering mutations (the Firefox script). Full argv are recorded per case.','']
(DEST/'README.md').write_text('\n'.join(lines))
print(json.dumps({'destination':str(DEST),'counts':summary['final_counts'],'bytes':(DEST/'case-evidence.tar.gz').stat().st_size,'changed_test_files':changed}))
